mapper.select:
SELECT *
FROM shopion.tPrdProd




    ORDER BY ${sidx} ${sord}
    ORDER BY ProdCode DESC

LIMIT ${pPageOffset}, ${pPageSize}

SELECT shopion.tPrdProd.*
, C.*, P.*, DF.*
FROM shopion.tPrdProd

LEFT OUTER JOIN (
    SELECT shopion.tStrProdCpn.*, tStrProdCpnProd.ProdCode, tStrProdCpnProd.ChnlCode
    FROM shopion.tStrProdCpn
    INNER JOIN shopion.tStrProdCpnProd ON shopion.tStrProdCpnProd.CpnId = shopion.tStrProdCpn.CpnId
        AND shopion.tStrProdCpnProd.ProdCode = #{pProdCode}
        AND shopion.tStrProdCpnProd.ChnlCode = #{pChnlCode}
) C ON shopion.tPrdProd.ProdCode = C.ProdCode
LEFT OUTER JOIN (
    SELECT shopion.tStrPoint.*, tStrPointProd.ProdCode, tStrPointProd.ChnlCode
    FROM shopion.tStrPoint
    INNER JOIN shopion.tStrPointProd ON shopion.tStrPointProd.PointId = shopion.tStrPoint.PointId
        AND shopion.tStrPointProd.ProdCode = #{pProdCode}
        AND shopion.tStrPointProd.ChnlCode = #{pChnlCode}
) P ON shopion.tPrdProd.ProdCode = P.ProdCode
LEFT OUTER JOIN shopion.tPrdProdDeliFee DF ON shopion.tPrdProd.DeliFeeId = DF.DeliFeeId

WHERE shopion.tPrdProd.ProdCode = #{pProdCode}

SELECT ProdCode
FROM shopion.tPrdProd
WHERE shopion.tPrdProd.ShopProdCode = #{value}

mapper.update:
UPDATE shopion.tPrdProd SET
    ReviewCntnts = #{reviewCntnts},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE ProdCode = #{prodCode}

mapper.select:
SELECT shopion.tPrdProd.*, C.*, P.* FROM shopion.tPrdProd LEFT OUTER JOIN ( SELECT shopion.tStrProdCpn.*, tStrProdCpnProd.ProdCode, tStrProdCpnProd.ChnlCode FROM shopion.tStrProdCpn INNER JOIN shopion.tStrProdCpnProd ON shopion.tStrProdCpnProd.CpnId = shopion.tStrProdCpn.CpnId AND shopion.tStrProdCpnProd.ChnlCode = #{pChnlCode} ) C ON shopion.tPrdProd.ProdCode = C.ProdCode LEFT OUTER JOIN ( SELECT shopion.tStrPoint.*, tStrPointProd.ProdCode, tStrPointProd.ChnlCode FROM shopion.tStrPoint INNER JOIN shopion.tStrPointProd ON shopion.tStrPointProd.PointId = shopion.tStrPoint.PointId AND shopion.tStrPointProd.ChnlCode = #{pChnlCode} ) P ON shopion.tPrdProd.ProdCode = P.ProdCode
ORDER BY shopion.tPrdProd.ProdCode DESC ORDER BY shopion.tPrdProd.ProdDsplName ASC ORDER BY shopion.tPrdProd.SalePrice ASC ORDER BY shopion.tPrdProd.SalePrice DESC
LIMIT #{topCnt}, #{countPerPage}

SELECT DISTINCT ProdDsplName
FROM shopion.tPrdProd




    ORDER BY

        CASE WHEN shopion.tPrdProd.SaleYn = 1 AND shopion.tPrdProd.SupplyQty > 0 THEN 0 ELSE 1 END,

    shopion.tPrdProd.${sidx} ${sord}

LIMIT #{topCnt}, #{countPerPage}
